class PhotoChallenge
{
  char gap0[8];
  int goal;
  int requiredScore;
  char gap10[4];
  bool recordChain;
  char gap15[27];

  class Photo
  {
    void *texture;
    int score;
    bool isOfSpecialTrick;

  public:
    int *GetScore(void) { return &score; }
    bool IsOfSpecialTrick(void) const { return isOfSpecialTrick; }
  };

  Photo *photos;

public:
  bool CheckForCompletion(void);
};

enum
{
  GOAL_PHOTO_1 = 7,
  GOAL_PHOTO_2,
  GOAL_PHOTO_3
};

bool PhotoChallenge::CheckForCompletion(void)
{
  bool completed = false;

  switch (goal)
  {
  case GOAL_PHOTO_1:
    if (!recordChain &&
        (*photos[0].GetScore() + *photos[1].GetScore() + *photos[2].GetScore() >= requiredScore))
      completed = true;
    break;

  case GOAL_PHOTO_2:
    if (!recordChain &&
        (*photos[0].GetScore() >= requiredScore || *photos[1].GetScore() >= requiredScore || *photos[2].GetScore() >= requiredScore))
      completed = true;
    break;

  case GOAL_PHOTO_3:
    if (!recordChain &&
        ((*photos[0].GetScore() >= requiredScore && photos[0].IsOfSpecialTrick()) ||
         (*photos[1].GetScore() >= requiredScore && photos[1].IsOfSpecialTrick()) ||
         (*photos[2].GetScore() >= requiredScore && photos[2].IsOfSpecialTrick())))
      completed = true;
    break;

  default:
    __builtin_trap();
  }

  return completed;
}
